const STORE='sari-app-v1';
const defaultPricing={agent:{device:45000,subscriptions:{1:18000,2:36000,3:54000}},headquarters:{device:50000,subscriptions:{1:25000,2:50000,3:75000}}};
const seed={agents:[{id:1,name:'أحمد الجبوري',phone:'0770 123 4567',code:'AG-001',price:18000},{id:2,name:'علي الكرخي',phone:'0781 456 7890',code:'AG-002',price:18500},{id:3,name:'حسن العبيدي',phone:'0750 321 9876',code:'AG-003',price:17500}],sales:[{id:1,name:'محمد كريم',type:'اشتراك جديد',seller:'المركز الرئيسي',amount:25000,paid:25000,date:today(),code:'SR-1001'},{id:2,name:'سعد ناصر',type:'جهاز جديد',seller:'أحمد الجبوري',amount:45000,paid:30000,date:today(),code:'SR-1002'},{id:3,name:'ضياء علي',type:'تجديد اشتراك',seller:'علي الكرخي',amount:18500,paid:18500,date:day(-1),code:'SR-1003'},{id:4,name:'قاسم فاضل',type:'جهاز جديد',seller:'المركز الرئيسي',amount:50000,paid:20000,date:day(-1),code:'SR-1004'},{id:5,name:'أوس مهدي',type:'اشتراك جديد',seller:'حسن العبيدي',amount:17500,paid:17500,date:day(-2),code:'SR-1005'}],debts:[{id:2,name:'سعد ناصر',phone:'0780 123 1122',source:'أحمد الجبوري',total:45000,paid:30000,due:day(4),note:'دفعة متبقية'},{id:4,name:'قاسم فاضل',phone:'0771 500 2211',source:'المركز الرئيسي',total:50000,paid:20000,due:day(2),note:'جهاز جديد'}],users:[{id:1,name:'مدير المركز',username:'admin',code:'SAR-ADMIN-01',role:'مدير رئيسي'},{id:2,name:'مشرف المبيعات',username:'sales-admin',code:'SAR-ADMIN-02',role:'أدمن'},{id:3,name:'مدير الحسابات',username:'accounts-admin',code:'SAR-ADMIN-03',role:'أدمن'},{id:4,name:'أحمد الجبوري',username:'ahmad.j',code:'AG-001',role:'وكيل'},{id:5,name:'علي الكرخي',username:'ali.k',code:'AG-002',role:'وكيل'},{id:6,name:'حسن العبيدي',username:'hasan.o',code:'AG-003',role:'وكيل'}]};
function today(){return new Date().toISOString().slice(0,10)}function day(n){let d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
let data;try{data=JSON.parse(localStorage.getItem(STORE))||structuredClone(seed)}catch{data=structuredClone(seed)}data.codes ||= [];data.agentSettlements ||= [];data.pricing ||= structuredClone(defaultPricing);data.pricing.agent ||= structuredClone(defaultPricing.agent);data.pricing.headquarters ||= structuredClone(defaultPricing.headquarters);for(const group of ['agent','headquarters'])data.pricing[group].subscriptions ||= structuredClone(defaultPricing[group].subscriptions);for(const user of data.users.filter(u=>u.role==='وكيل')){if(!data.agents.some(a=>a.code===user.code||a.name===user.name))data.agents.push({id:user.id,name:user.name,phone:user.phone||'—',code:user.code,price:Number(data.pricing.agent.device)||0})}let view='home',filter='',debtFilter='',agentPanel='sales',query='',installPrompt=null,qrStream=null,agentSort='asc';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=x=>Number(x||0).toLocaleString('en-US'),save=()=>{localStorage.setItem(STORE,JSON.stringify(data));if(window.SariCloud?.profile()?.role==='admin')return window.SariCloud.save(data).then(()=>{notify('تم حفظ البيانات بنجاح');return true}).catch(error=>{notify(error?.message||'تعذر حفظ البيانات في Firebase');return false});notify('تم حفظ البيانات على هذا الجهاز');return Promise.resolve(true);};
function date(x){try{return new Intl.DateTimeFormat('en-US',{day:'numeric',month:'short',year:'numeric'}).format(new Date(x+'T12:00:00'))}catch{return x}}function addMonths(dateValue,months){let [y,m,d]=String(dateValue||today()).split('-').map(Number),target=new Date(y,m-1+Number(months),1),last=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();target.setDate(Math.min(d,last));return `${target.getFullYear()}-${String(target.getMonth()+1).padStart(2,'0')}-${String(target.getDate()).padStart(2,'0')}`}function initials(n){return String(n||'').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('')}
function fld(label,name,type='text',options={}){let full=options.full?' full':'',required=options.required===false?'':' required',value=options.value??'',placeholder=options.placeholder?` placeholder="${esc(options.placeholder)}"`:'',attrs=`${options.min!==undefined?` min="${esc(options.min)}"`:''}${options.max!==undefined?` max="${esc(options.max)}"`:''}${options.step!==undefined?` step="${esc(options.step)}"`:''}`;let control=type==='select'?`<select name="${esc(name)}"${required}>${(options.options||[]).map(x=>`<option value="${esc(x.value)}"${String(x.value)===String(value)?' selected':''}>${esc(x.label)}</option>`).join('')}</select>`:`<input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}"${required}${placeholder}${attrs}>`;return `<div class="field${full}"><label for="${esc(name)}">${esc(label)}</label>${control}</div>`}
function notify(s){let t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>t.classList.remove('show'),2400)}function badge(){ $('#sales-badge').textContent=data.sales.length;$('#debts-badge').textContent=data.debts.length;let now=new Date(),dateText=new Intl.DateTimeFormat('ar-IQ-u-nu-latn',{weekday:'long',day:'numeric',month:'long'}).format(now),timeText=new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit'}).format(now);$('#today').textContent=`${dateText} · ${timeText}` }
function heading(title,sub,action=''){let greet=view==='home'?(new Date().getHours()<12?'صباح الخير، أهلاً بك':'مساء الخير، أهلاً بك'):'إدارة النظام';return `<div class="heading"><div><small>${greet}</small><h1>${title}</h1><p>${sub}</p></div>${action?`<div class="heading-actions"><button class="button primary" data-action="${action}"><span class="plus">＋</span>${({sale:'تسجيل عملية بيع',agent:'إضافة وكيل',debt:'إضافة دين',user:'إضافة مستخدم',code:'توليد أكواد'})[action]}</button>${action==='sale'?'<button class="button primary" data-action="agent-invoice">تسجيل عملية بيع للوكيل</button>':''}</div>`:''}</div>`}
function stat(name,value,unit,icon,foot){return `<div class="stat"><div class="stat-top"><span>${name}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}<small>${unit||''}</small></div><div class="stat-foot">${foot}</div></div>`}
function state(paid,amount){return paid>=amount?'<span class="status">مكتمل</span>':'<span class="status debt">عليه دين</span>'}
function priceSchedule(seller,type,saleType=''){let schedule=seller==='المركز الرئيسي'?data.pricing.headquarters:data.pricing.agent;if(saleType==='جهاز جديد'||type.includes('جهاز'))return{key:'device',amount:Number(schedule.device)||0};let months=type.includes('3')||type.includes('ثلاث')?3:type.includes('2')||type.includes('شهرين')?2:1;return{key:`subscription_${months}m`,amount:Number(schedule.subscriptions[months])||0}}
function pricesPage(){let group=(key,title,sub)=>`<section class="panel price-panel"><div class="panel-head"><div><b>${title}</b><small>${sub}</small></div></div><div class="price-fields">${[['device','سعر الجهاز'],['subscriptions.1','اشتراك شهر واحد'],['subscriptions.2','اشتراك شهرين'],['subscriptions.3','اشتراك 3 أشهر']].map(([field,label])=>{let value=field==='device'?data.pricing[key].device:data.pricing[key].subscriptions[field.split('.')[1]];return `<label class="price-field"><span>${label}</span><div><input type="number" min="0" step="1" name="${key}.${field}" value="${Number(value)||0}" required><small>د.ع</small></div></label>`}).join('')}</div></section>`;return `${heading('الأسعار','حدد أسعار العمليات الجديدة من مكان واحد. تُحفظ قيمة السعر داخل كل عملية عند تسجيلها.')}<form id="pricing-form"><div class="pricing-grid">${group('agent','أسعار الوكلاء','الأسعار المستحقة على الوكيل مقابل كل تفعيل أو تجديد.')}${group('headquarters','أسعار الرئيسية المباشرة','أسعار بيع الرئيسية للزبون النهائي.')}</div><div class="pricing-save-row"><button class="button primary" type="submit">حفظ الأسعار</button><span>تغييرات الأسعار لا تؤثر على العمليات السابقة.</span></div></form>`}
function home(){let total=data.sales.reduce((a,x)=>a+x.amount,0),ts=data.sales.filter(x=>x.date===today()),owed=data.debts.reduce((a,x)=>a+x.total-x.paid,0);let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let k=d.toISOString().slice(0,10);return{label:new Intl.DateTimeFormat('ar-IQ',{weekday:'short'}).format(d),n:data.sales.filter(x=>x.date===k).reduce((a,x)=>a+x.amount,0)}});let max=Math.max(...days.map(d=>d.n),1),coords=days.map((d,i)=>`${35+i*105},${150-d.n/max*113}`).join(' ');let rows=[...data.sales].sort((a,b)=>b.id-a.id);return `${heading('نظرة عامة','تابع أداء المركز والوكلاء من لوحة واحدة.','sale')}<div class="stats">${stat('إجمالي المبيعات',money(total),'د.ع','↗',data.sales.length+' عملية مسجلة')}${stat('مبيعات اليوم',money(ts.reduce((a,x)=>a+x.amount,0)),'د.ع','◷',ts.length+' عمليات اليوم')}${stat('الوكلاء النشطون',data.agents.length,'وكيل','♧','حسابات الوكلاء المسجلة')}${stat('الديون المستحقة',money(owed),'د.ع','◉',data.debts.length+' سجلات مفتوحة')}</div><div class="panels"><section class="panel"><div class="panel-head"><div><b>حركة المبيعات</b><small>مجموع المبيعات خلال آخر ٧ أيام</small></div><span class="role">آخر أسبوع</span></div><div class="chart-wrap"><svg class="chart" viewBox="0 0 700 180" preserveAspectRatio="none"><defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#7899b4" stop-opacity=".25"/><stop offset="1" stop-color="#7899b4" stop-opacity="0"/></linearGradient></defs><line class="gridline" x1="30" y1="37" x2="680" y2="37"/><line class="gridline" x1="30" y1="75" x2="680" y2="75"/><line class="gridline" x1="30" y1="112" x2="680" y2="112"/><line class="gridline" x1="30" y1="150" x2="680" y2="150"/><polygon class="area" points="35,150 ${coords} 665,150"/><polyline class="line" points="${coords}"/>${days.map((d,i)=>`<circle class="point" cx="${35+i*105}" cy="${150-d.n/max*113}" r="3.5"/><text class="axis" x="${35+i*105}" y="173" text-anchor="middle">${d.label}</text>`).join('')}</svg></div></section><section class="panel"><div class="panel-head"><div><b>آخر العمليات</b><small>أحدث الحركات المسجلة</small></div><button class="link" data-view="sales">عرض الكل ←</button></div><div class="activity">${rows.slice(0,4).map(s=>`<div class="activity-row"><span class="activity-ico ${s.paid<s.amount?'warn':''}">${s.paid<s.amount?'◷':'↗'}</span><div class="activity-info"><b>${esc(s.name)}</b><small>${esc(s.seller)} · ${date(s.date)}</small></div><span class="amount">${money(s.amount)} د.ع</span></div>`).join('')}</div></section></div><section class="panel table-panel"><div class="panel-head"><div><b>أحدث المبيعات</b><small>آخر عمليات البيع المسجلة</small></div><button class="link" data-view="sales">كل المبيعات ←</button></div>${salesTable(rows.slice(0,5),false)}</section>`}
function salesTable(rows,full=true){return `<div class="table-scroll"><table class="${full?'sales-record-table':''}"><thead><tr>${full?'<th>الزبون / الفاتورة</th><th>نوع البيع</th><th>اسم الوكيل</th><th>البائع</th><th>رقم الجهاز</th><th>نوع الاشتراك / الكميات</th><th>بدء الاشتراك</th><th>انتهاء الاشتراك</th><th>السعر / الإجمالي</th><th>التسديد</th><th>الحالة</th><th>التاريخ</th><th></th>':'<th>الزبون / الفاتورة</th><th>نوع البيع</th><th>البائع</th><th>المبلغ</th><th>الحالة</th><th>التاريخ</th>'}</tr></thead><tbody>${rows.map(s=>{let invoice=s.saleType==='فاتورة وكيل';return `<tr class="${s.agentRequestPending?'sale-pending-admin':''}">${full?`<td><div class="customer"><span class="face">${esc(initials(s.name))}</span><b>${esc(s.name)}</b></div></td><td>${esc(s.saleType||(s.type.includes('جهاز')?'جهاز جديد':'تجديد اشتراك'))}</td><td>${s.seller==='المركز الرئيسي'?'—':esc(s.agentName||s.seller)}</td><td>${esc(s.seller)}</td><td>${s.deviceNo?`<button type="button" class="sale-device-number" data-qr="${esc(s.deviceNo)}">${esc(s.deviceNo)}</button>`:'—'}</td><td>${invoice?`${Number(s.subscriptionCount)||0} اشتراك · ${Number(s.deviceCount)||0} جهاز`:esc(s.type)}</td><td>${s.startDate?date(s.startDate):'—'}</td><td>${s.endDate?date(s.endDate):'—'}</td><td>${money(invoice?s.invoiceTotal:s.amount)} د.ع</td><td>${s.agentRequestPending?`<select class="sale-payment-select" data-admin-payment="${s.id}" aria-label="تحديد تسديد ${esc(s.name)}"><option value="">تحديد نقد أو دين</option><option value="نقد">نقد</option><option value="دين">دين</option></select>`:esc(s.paymentMethod|| (s.paid>=s.amount?'نقد':'دين'))}</td><td>${state(s.paid,s.amount)}</td><td>${date(s.date)}</td><td><button class="user-edit" data-edit-sale="${s.id}">تعديل</button><button class="row-action" data-delete="sale" data-id="${s.id}">حذف</button></td>`:`<td><div class="customer"><span class="face">${esc(initials(s.name))}</span><b>${esc(s.name)}</b></div></td><td>${esc(s.saleType||(s.type.includes('جهاز')?'جهاز جديد':'تجديد اشتراك'))}</td><td>${esc(s.seller)}</td><td>${money(invoice?s.invoiceTotal:s.amount)} د.ع</td><td>${state(s.paid,s.amount)}</td><td>${date(s.date)}</td>`}</tr>`}).join('')}</tbody></table>${rows.length?'':'<div class="empty"><b>لا توجد عمليات بيع</b>سجّل أول عملية بيع لعرضها هنا.</div>'}</div>`}
function salesPage(){let rows=[...data.sales].sort((a,b)=>b.id-a.id).filter(x=>(!filter||x.seller===filter)&&(`${x.name} ${x.seller} ${x.type}`.includes(query)));return `${heading('المبيعات','سجل ومتابعة مبيعات المركز والوكلاء.','sale')}<div class="stats">${stat('عدد العمليات',data.sales.length,'عملية','↗','عمليات البيع المسجلة')}${stat('إجمالي المبيعات',money(data.sales.reduce((a,x)=>a+x.amount,0)),'د.ع','◈','قيمة المبيعات')}${stat('المبالغ المستلمة',money(data.sales.reduce((a,x)=>a+x.paid,0)),'د.ع','✓','المبالغ المحصلة')}${stat('المتبقي للتحصيل',money(data.sales.reduce((a,x)=>a+x.amount-x.paid,0)),'د.ع','◷','عمليات البيع الآجلة')}</div><section class="panel"><div class="panel-head"><div><b>سجل المبيعات</b><small>${filter?'مبيعات '+esc(filter):'جميع المبيعات'}</small></div></div><div class="sales-filter-bar" role="group" aria-label="تصفية حسب البائع"><button type="button" class="sales-filter ${filter===''?'active':''}" data-sales-filter="">الكل</button><button type="button" class="sales-filter ${filter==='المركز الرئيسي'?'active':''}" data-sales-filter="المركز الرئيسي">الرئيسية</button>${data.agents.map(a=>`<button type="button" class="sales-filter ${filter===a.name?'active':''}" data-sales-filter="${esc(a.name)}">${esc(a.name)}</button>`).join('')}</div><div class="toolbar"><label class="search"><span>⌕</span><input id="query" placeholder="ابحث عن زبون أو وكيل" value="${esc(query)}"></label></div>${salesTable(rows,true)}</section>`}
function agentsPage(){let amt=data.sales.filter(s=>s.seller!=='المركز الرئيسي').reduce((a,s)=>a+s.amount,0),agents=[...data.agents].sort((a,b)=>agentSort==='asc'?a.name.localeCompare(b.name,'ar'):b.name.localeCompare(a.name,'ar')),dueOf=s=>s.agentRequestPending?0:Math.max(0,s.amount-(s.agentPaid||0));return `${heading('الوكلاء','إدارة الوكلاء وأسعارهم ومتابعة مبيعات كل وكيل.','agent')}<div class="stats">${stat('عدد الوكلاء',data.agents.length,'وكيل','♧','الوكلاء المسجلون')}${stat('عمليات الوكلاء',data.sales.filter(s=>s.seller!=='المركز الرئيسي').length,'عملية','↗','عبر شبكة الوكلاء')}${stat('مبيعات الوكلاء',money(amt),'د.ع','◈','قيمة المبيعات')}${stat('سعر المركز المباشر',money(data.pricing.headquarters.device),'د.ع','⌂','السعر الافتراضي')}</div><div class="agents">${agents.map(a=>{let ss=data.sales.filter(s=>s.seller===a.name),unpaid=ss.filter(s=>dueOf(s)>0),due=unpaid.reduce((n,s)=>n+dueOf(s),0);return `<article class="agent-card"><div class="agent-head"><span class="agent-face">${esc(initials(a.name))}</span><span class="agent-name"><b>${esc(a.name)}</b><small>${esc(a.code)} · ${esc(a.phone)}</small></span><button class="button primary settle-agent" data-settle-agent="${a.id}" ${unpaid.length?'':'disabled'}>تسديد الديون (${unpaid.length})</button><button class="agent-more" data-edit-agent="${a.id}">تعديل</button></div><div class="agent-kpis"><div><small>سعر الوكيل</small><b>${money(data.pricing.agent.device)} <small>د.ع</small></b></div><div><small>إجمالي المبيعات</small><b>${money(ss.reduce((x,s)=>x+s.amount,0))} <small>د.ع</small></b></div></div><div class="agent-foot"><small>${ss.length} عمليات · الدين ${money(due)} د.ع</small><button data-agent-sales="${esc(a.name)}">عرض المبيعات ←</button></div></article>`}).join('')||'<div class="panel empty">لا يوجد وكلاء مسجلون</div>'}</div><section class="panel table-panel"><div class="panel-head"><div><b>مبيعات الوكلاء غير المسددة</b><small>إجمالي المستحق ${money(data.sales.filter(s=>s.seller!=='المركز الرئيسي').reduce((n,s)=>n+dueOf(s),0))} د.ع</small></div><label class="agent-sort">ترتيب الوكيل <select id="agent-sort" value="${agentSort}"><option value="asc" ${agentSort==='asc'?'selected':''}>الاسم: أ إلى ي</option><option value="desc" ${agentSort==='desc'?'selected':''}>الاسم: ي إلى أ</option></select></label></div><div class="table-scroll"><table><thead><tr><th>الوكيل</th><th>الزبون</th><th>نوع البيع</th><th>قيمة البيع</th><th>المستحق للوكيل</th></tr></thead><tbody>${data.sales.filter(s=>s.seller!=='المركز الرئيسي'&&dueOf(s)>0).sort((a,b)=>agentSort==='asc'?a.seller.localeCompare(b.seller,'ar'):b.seller.localeCompare(a.seller,'ar')).map(s=>`<tr><td>${esc(s.seller)}</td><td>${esc(s.name)}</td><td>${esc(s.type)}</td><td>${money(s.amount)} د.ع</td><td>${money(dueOf(s))} د.ع</td></tr>`).join('')||'<tr><td colspan="5">لا توجد مبيعات مستحقة على الوكلاء.</td></tr>'}</tbody></table></div></section>`}
function agentSettlementPanel(){return `<section class="panel table-panel"><div class="panel-head"><div><b>سجل تسديدات الوكلاء</b><small>المبلغ المستحق والمقبوض والفرق المسجل</small></div></div><div class="table-scroll"><table><thead><tr><th>التاريخ</th><th>الوكيل</th><th>عدد السطور</th><th>المستحق</th><th>المقبوض</th><th>الفرق</th></tr></thead><tbody>${[...data.agentSettlements].reverse().map(x=>`<tr><td>${date(x.date)}</td><td>${esc(x.agent)}</td><td>${x.saleIds.length}</td><td>${money(x.salesTotal)} د.ع</td><td>${money(x.received)} د.ع</td><td>${x.variance>0?'+':''}${money(x.variance)} د.ع</td></tr>`).join('')||'<tr><td colspan="6">لا توجد تسديدات مسجلة.</td></tr>'}</tbody></table></div></section>`}
