function pay(id){let d=data.debts.find(x=>x.id===id),left=d.total-d.paid;open('تسجيل دفعة',`<div class="field full"><label>المتبقي قبل الدفعة</label><b>${money(left)} د.ع</b></div><div class="field full"><label>قيمة الدفعة (د.ع)</label><input name="amount" type="number" min="0.01" max="${left}" step="any" required><small class="payment-remaining">المتبقي بعد الدفعة: <b id="pay-remaining">${money(left)} د.ع</b></small></div>`,o=>{let n=Number(o.amount);if(!Number.isFinite(n)||n<=0||n>left){notify('أدخل مبلغاً أكبر من صفر ولا يتجاوز المتبقي');return false}d.paid=Math.min(d.total,d.paid+n);let sale=data.sales.find(s=>s.id===d.id&&s.paid<s.amount)||data.sales.find(s=>s.name===d.name&&s.seller===d.source&&s.paid<s.amount);if(sale){sale.paid=Math.min(sale.amount,sale.paid+n);sale.paymentMethod=sale.paid>=sale.amount?'نقد':'دين'}if(d.paid>=d.total)data.debts=data.debts.filter(x=>x.id!==id);save();notify(`تم تسجيل دفعة ${money(n)} د.ع`)})}
