function generateCodes(){let input=String($('#code-count')?.value||'').trim(),known=new Set(data.codes.map(x=>String(x.value))),normalized=input.replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[\s-]/g,''),count=Number.parseInt(normalized,10);if(normalized&&/^\d+$/.test(normalized)){if(Number.isInteger(count)&&count>1&&count<=500){let values=[],attempts=0;while(values.length<count&&attempts<count*50){attempts++;let v;do{const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);v=Array.from(bytes,x=>x%10).join('');if(v[0]==='0')v='1'+v.slice(1)}while(known.has(v)||values.includes(v));known.add(v);values.push(v)}if(!values.length){notify('تعذر توليد أكواد فريدة. حاول مرة أخرى');return}values.forEach(v=>data.codes.unshift({value:v,status:'متاح',date:today()}));save();render();notify(`تم توليد ${values.length} كود فريد`);return}if(known.has(normalized)){notify('هذا الرقم مسجل مسبقاً');return}data.codes.unshift({value:normalized,status:'متاح',date:today()});save();render();notify('تمت إضافة الرقم وإنشاء QR');return}let n=Number.isInteger(count)&&count>0?count:1,values=[],attempts=0;while(values.length<n&&attempts<n*50){attempts++;let v;do{const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);v=Array.from(bytes,x=>x%10).join('');if(v[0]==='0')v='1'+v.slice(1)}while(known.has(v)||values.includes(v));known.add(v);values.push(v)}if(!values.length){notify('تعذر توليد أكواد فريدة. حاول مرة أخرى');return}values.forEach(v=>data.codes.unshift({value:v,status:'متاح',date:today()}));save();render();notify(`تم توليد ${values.length} كود فريد`)}
