function showQr(value){let dlg=$('#qr-modal');if(!dlg){document.body.insertAdjacentHTML('beforeend','<dialog id="qr-modal" class="sale-qr-dialog"><div class="scanner-box"><div class="modal-head"><div><small>باركود رقم الجهاز</small><h2 id="qr-title"></h2></div><button type="button" class="close" id="qr-close">×</button></div><div id="qr-preview" class="qr-preview"></div><button type="button" class="button primary" id="qr-download">تنزيل صورة الباركود</button></div></dialog>');dlg=$('#qr-modal')}$('#qr-title').textContent=value;dlg.onclick=e=>{if(e.target===dlg)dlg.close()};dlg.showModal();makeQr($('#qr-preview'),value,260);$('#qr-download').onclick=()=>{let c=$('#qr-preview canvas');if(!c){notify('لم يتولد الرمز بعد');return}let a=document.createElement('a');a.download=`sari-${value}.png`;a.href=c.toDataURL('image/png');a.click()}}
