async function printCodes(){let vals=selectedCodes();if(!vals.length){notify('أضف أكواداً أولاً');return}if(typeof QRCode==='undefined'){notify('مولّد QR يتطلب اتصالاً بالإنترنت');return}let host=$('#codes-print-content');if(!host){document.body.insertAdjacentHTML('beforeend','<dialog id="codes-print-modal" class="codes-print-modal"><div class="codes-print-toolbar"><b>معاينة الأكواد للطباعة</b><div><button type="button" id="codes-print-now" class="button primary">طباعة / حفظ PDF</button><button type="button" id="codes-print-close" class="button secondary">إغلاق</button></div></div><div id="codes-print-content" class="codes-print-content"></div></dialog>');host=$('#codes-print-content');$('#codes-print-close').onclick=()=>$('#codes-print-modal').close();$('#codes-print-modal').addEventListener('click',e=>{if(e.target===$('#codes-print-modal'))$('#codes-print-modal').close()});$('#codes-print-now').onclick=()=>window.print()}let pages=[];let p=0,page=0;while(p<vals.length){let count=page%2===0?8:6,items=vals.slice(p,p+count);pages.push(`<section class="codes-print-sheet ${page%2===0?'pdf-four-rows':'pdf-three-rows'}"><div class="codes-print-grid">${items.map((v,i)=>`<div class="codes-print-item"><div id="print-q${p+i}" class="codes-print-qr"></div><b class="codes-print-code">${esc(v)}</b></div>`).join('')}</div></section>`);p+=count;page++}host.innerHTML=pages.join('');$('#codes-print-modal').showModal();vals.forEach((v,i)=>{let target=$(`#print-q${i}`);new QRCode(target,{text:v,width:420,height:420,colorDark:'#000000',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H})})}
function exportSheet(name,rows){if(typeof XLSX!=='undefined'){let ws=XLSX.utils.json_to_sheet(rows);let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'الساري');XLSX.writeFile(wb,`الساري-${name}.xlsx`);return}let keys=Object.keys(rows[0]||{}),csv='\ufeff'+[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`الساري-${name}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function reportRows(kind){if(kind==='codes')return data.codes.map(c=>({الكود:c.value,الحالة:c.status,التاريخ:c.date}));if(kind==='sales')return data.sales.map(s=>({رقم_العملية:s.code,الزبون_أو_الفاتورة:s.name,النوع:s.saleType==='فاتورة وكيل'?'فاتورة وكيل':s.type,الوكيل:s.agentName||'',عدد_الاشتراكات:s.subscriptionCount??'',عدد_الأجهزة:s.deviceCount??'',السعر_الكلي_للفاتورة:s.invoiceTotal??'',البائع:s.seller,المبلغ:s.amount,السعر_وقت_العملية:s.pricingSnapshot?.unitPrice??s.amount,مصدر_التسعير:s.pricingSnapshot?.source==='agent'?'الوكيل':'الرئيسية',المدفوع:s.paid,المتبقي:s.amount-s.paid,التاريخ:s.date}));if(kind==='debts')return data.debts.map(d=>({الزبون:d.name,الهاتف:d.phone,المصدر:d.source,المبلغ:d.total,المدفوع:d.paid,المتبقي:d.total-d.paid,الاستحقاق:d.due}));return data.agents.map(a=>({الوكيل:a.name,الهاتف:a.phone,سعر_الجهاز_للوكيل:data.pricing.agent.device,عدد_المبيعات:data.sales.filter(s=>s.seller===a.name).length,إجمالي_المبيعات:data.sales.filter(s=>s.seller===a.name).reduce((x,s)=>x+s.amount,0)}))}
function printReport(kind){let rows=reportRows(kind);let win=window.open('','_blank');if(!win){notify('اسمح بالنوافذ المنبثقة للتقرير');return}let title=kind==='sales'?'تقرير المبيعات':kind==='debts'?'تقرير الديون':'تقرير الوكلاء',keys=Object.keys(rows[0]||{});win.document.write(`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>${title}</title><style>body{font:13px Arial,Tahoma;padding:20px;color:#111}h1{font-size:22px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #555;padding:8px;text-align:right}th{background:#eee}@media print{body{padding:0}}</style><h1>الساري - ${title}</h1><p>تاريخ التقرير: ${date(today())}</p><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></html>`);win.document.close()}
async function importCodes(file){try{let rows;if(typeof XLSX!=='undefined'){let wb=XLSX.read(await file.arrayBuffer(),{type:'array',raw:false});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:'',raw:false}).flat()}else{rows=(await file.text()).split(/[\r\n,;\t]+/)}let known=new Set(data.codes.map(x=>x.value)),added=0;for(let cell of rows){let v=String(cell??'').trim().replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[\s-]/g,'');if(/^\d+$/.test(v)&&!known.has(v)){data.codes.unshift({value:v,status:'متاح',date:today()});known.add(v);added++}}save();render();notify(added?`تم استيراد ${added} رقماً`:'لم يتم العثور على أرقام جديدة')}catch(e){notify('تعذّر قراءة الملف. استخدم XLSX أو CSV')}finally{let input=$('#code-file');if(input)input.value=''}}
function stopScanner(){if(qrStream){qrStream.getTracks().forEach(t=>t.stop());qrStream=null}}
function addScannedCode(raw){let v=String(raw||'').trim().replace(/[\s-]/g,'');if(!/^\d{16}$/.test(v)){notify('الكود يجب أن يتكون من 16 رقماً');return false}if(data.codes.some(x=>x.value===v)){notify('هذا الكود مسجل مسبقاً');return false}data.codes.unshift({value:v,status:'متاح',date:today()});save();render();notify('تمت إضافة الكود الممسوح');return true}
function startScanner(target='inventory'){scanTarget=target;let dlg=$('#scanner-modal');dlg.showModal();let video=$('#scan-video');if(!$('#manual-code'))video.insertAdjacentHTML('afterend','<div class="manual-scan"><label for="manual-code">أو أدخل رقم الجهاز / الكود يدوياً</label><div><input id="manual-code" inputmode="numeric" placeholder="الرقم"><button id="manual-add" class="button primary">استخدام الرقم</button></div></div>');$('#manual-code').value='';$('#scan-message').textContent='وجّه الكاميرا نحو باركود الجهاز أو أدخل الرقم يدوياً.';if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){$('#scan-message').textContent='المسح بالكاميرا غير مدعوم؛ استخدم الإدخال اليدوي.';return}video.style.display='block';navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false}).then(async stream=>{if(!dlg.open){stream.getTracks().forEach(t=>t.stop());return}qrStream=stream;video.srcObject=stream;await video.play();let detector=new BarcodeDetector({formats:['qr_code','code_128','ean_13','ean_8']});let scan=async()=>{if(!dlg.open)return;try{let found=await detector.detect(video);if(found.length){let val=found[0].rawValue.trim();if(target==='sale'){let device=$('#fields [name="deviceNo"]');if(device){device.value=val;device.dispatchEvent(new Event('input',{bubbles:true}))}stopScanner();dlg.close();notify('تمت قراءة رقم الجهاز');return}if(addScannedCode(val)){stopScanner();dlg.close();return}}}catch{}requestAnimationFrame(scan)};requestAnimationFrame(scan)}).catch(()=>{$('#scan-message').textContent='تعذّر فتح الكاميرا؛ استخدم الإدخال اليدوي.'})}
